/*
 * One family's prose, fetched one family at a time.
 *
 * The glob is deliberately not eager. With `eager: true` Vite inlines every file
 * it matched into whatever chunk imports this module, which is the thing being
 * avoided; without it, each match becomes its own dynamic import, so
 * /applications/vfd asks for vfd.json and nothing else. Thirty-six imports are
 * declared, one is fetched.
 *
 * The files are generated by tools/family-index.mjs before the module graph is
 * read, so the glob cannot see a stale set: the directory is cleared and rewritten
 * from applicationFamilies.js on every build.
 *
 * Nothing here runs during the prerender. renderToString cannot await a promise,
 * so entry-server.jsx keeps its own eager copy of the same files and hands the
 * result to the page as a prop. This module is the browser's half of that split.
 */

const BODIES = import.meta.glob('../data/families/*.json');

export const FAMILY_BODY_COUNT = Object.keys(BODIES).length;

export function loadFamilyBody(slug) {
  const load = BODIES[`../data/families/${slug}.json`];
  return load
    ? load().then((m) => m.default)
    : Promise.reject(new Error(`no content file for family "${slug}"`));
}
